            payable(address(c)).transfer(initialDeposit);
        }

        // Owner calls withdrawAll
        vm.prank(c.owner());
        c.withdrawAll();

        // Rule: after withdrawAll, contract balance must be zero
        assertTrue(address(c).balance == 0);
    }
}

