pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound the amount to a reasonable range to avoid overflow and ensure enough funds are available for setup
        amount = bound(amount, 1, address(this).balance / 2);

        // Fund the contract with the fuzzed amount
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "Funding failed");

        uint256 balanceBefore = address(c).balance;

        // Trigger the operation under test
        vm.prank(c.owner());
        c.withdrawAll();

        uint256 balanceAfter = address(c).balance;

        // General rule: after withdrawAll, either the balance is 0, or the balance before must be strictly greater than 2 * balanceAfter.
        // This ensures the withdrawal removed more than half of the balance.
        // The correct contract withdraws everything, so balanceAfter == 0 (rule satisfied).
        // The buggy contract withdraws only half, so if balanceAfter > 0, then balanceBefore == 2 * balanceAfter (rule violated).
        assertTrue(balanceAfter == 0 || balanceBefore > 2 * balanceAfter);
    }
}

