import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0x1234);

    function setUp() public {
        vm.prank(owner);
        c = new C();
    }

    function testFuzz_property(uint256 initialBalance, uint256 extraDeposit) public {
        // Limit balances to avoid overflow and keep values reasonable for transfer
        bound(initialBalance, 1, 100 ether);
        bound(extraDeposit, 0, 100 ether);

        // Fund the contract via fallback deposits from various senders
        address depositor1 = address(0xabcd);
        address depositor2 = address(0xbeef);
        vm.deal(depositor1, initialBalance);
        vm.prank(depositor1);
        (bool s1, ) = address(c).call{value: initialBalance}("");
        require(s1, "deposit1 failed");

        if (extraDeposit > 0) {
            vm.deal(depositor2, extraDeposit);
            vm.prank(depositor2);
            (bool s2, ) = address(c).call{value: extraDeposit}("");
            require(s2, "deposit2 failed");
        }

        uint256 ownerBalanceBefore = owner.balance;

        bool success;
        vm.prank(owner);
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }

        uint256 ownerBalanceAfter = owner.balance;

        // The reference always sends the full balance to owner, so owner balance must increase.
        // Bug: withdrawAll call succeeds but no transfer occurs, so owner gets nothing.
        assertTrue(success && ownerBalanceAfter > ownerBalanceBefore);
    }
